import type { PostgrestError } from '@supabase/supabase-js'
import { invokeFunction } from '@/lib/functions'
import { getSupabase } from '@/lib/supabase'
import {
  normalizePhone,
  statusForParticipantCount,
  type ExchangeStatus,
  type ParticipantInput,
} from '@/utils/exchangeRules'

// Reads/writes the same tables as the mobile app, scoped by the existing
// organizer RLS policies. Assignments are generated by the draw-exchange
// Edge Function and are never read here.

export type ExchangeSummary = {
  id: string
  name: string
  exchangeDate: string | null
  minimumBudget: number | null
  maximumBudget: number | null
  status: ExchangeStatus
  participantCount: number
}

export type Participant = { id: string; name: string; phoneNumber: string }

export type ExchangeDetail = ExchangeSummary & {
  inviteCode: string
  participants: Participant[]
  hasSubgroupRules: boolean
  allowDoubleGifts: boolean
}

export type ExchangeDetailsInput = {
  name: string
  exchangeDate?: string
  minimumBudget?: number
  maximumBudget?: number
}

const SUMMARY_COLUMNS =
  'id, name, exchange_date, minimum_budget, maximum_budget, status, updated_at, participants(count)'

type SummaryRow = {
  id: string
  name: string
  exchange_date: string | null
  minimum_budget: number | null
  maximum_budget: number | null
  status: ExchangeStatus
  participants: Array<{ count: number }>
}

type ParticipantRow = { id: string; name: string; phone_number: string; created_at: string }

type DetailRow = Omit<SummaryRow, 'participants'> & {
  invite_code: string
  prevent_subgroup_matches: boolean
  allow_double_gifts: boolean
  participants: ParticipantRow[]
}

function fail(error: PostgrestError, fallback: string): never {
  console.error('[exchanges]', error.code, error.message)
  if (error.code === '23505') throw new Error('This person is already in the exchange')
  throw new Error(fallback)
}

async function currentUserId(): Promise<string> {
  const { data } = await getSupabase().auth.getSession()
  const userId = data.session?.user.id
  if (!userId) throw new Error('Please log in again.')
  return userId
}

function groupPayload(input: ExchangeDetailsInput) {
  return {
    name: input.name.trim(),
    exchange_date: input.exchangeDate?.trim() || null,
    minimum_budget: input.minimumBudget ?? null,
    maximum_budget: input.maximumBudget ?? null,
  }
}

function participantPayload(input: ParticipantInput) {
  return {
    name: input.name.trim(),
    phone_number: input.phoneNumber.trim(),
    phone_normalized: normalizePhone(input.phoneNumber),
  }
}

export async function listExchanges(): Promise<ExchangeSummary[]> {
  const { data, error } = await getSupabase()
    .from('groups')
    .select(SUMMARY_COLUMNS)
    .order('updated_at', { ascending: false })
  if (error) fail(error, "Couldn't load your exchanges. Please try again.")

  return ((data ?? []) as SummaryRow[]).map((row) => ({
    id: row.id,
    name: row.name,
    exchangeDate: row.exchange_date,
    minimumBudget: row.minimum_budget,
    maximumBudget: row.maximum_budget,
    status: row.status,
    participantCount: row.participants[0]?.count ?? 0,
  }))
}

export async function getExchange(id: string): Promise<ExchangeDetail | null> {
  const supabase = getSupabase()
  const { data, error } = await supabase
    .from('groups')
    .select(
      'id, name, exchange_date, minimum_budget, maximum_budget, status, invite_code, prevent_subgroup_matches, allow_double_gifts, participants(id, name, phone_number, created_at)',
    )
    .eq('id', id)
    .maybeSingle()
  if (error) {
    if (error.code === '22P02') return null
    fail(error, "Couldn't load this exchange. Please try again.")
  }
  if (!data) return null

  const row = data as DetailRow
  const participants = [...row.participants]
    .sort((a, b) => a.created_at.localeCompare(b.created_at))
    .map((p) => ({ id: p.id, name: p.name, phoneNumber: p.phone_number }))

  return {
    id: row.id,
    name: row.name,
    exchangeDate: row.exchange_date,
    minimumBudget: row.minimum_budget,
    maximumBudget: row.maximum_budget,
    status: row.status,
    participantCount: participants.length,
    inviteCode: row.invite_code,
    participants,
    hasSubgroupRules: row.prevent_subgroup_matches,
    allowDoubleGifts: row.allow_double_gifts,
  }
}

export async function createExchange(
  details: ExchangeDetailsInput,
  participants: ParticipantInput[],
): Promise<string> {
  const supabase = getSupabase()
  const organizerId = await currentUserId()

  const { data: group, error } = await supabase
    .from('groups')
    .insert({
      ...groupPayload(details),
      organizer_id: organizerId,
      status: statusForParticipantCount(participants.length),
    })
    .select('id')
    .single()
  if (error) fail(error, "Couldn't create your exchange. Please try again.")

  if (participants.length > 0) {
    const { error: participantError } = await supabase
      .from('participants')
      .insert(participants.map((p) => ({ ...participantPayload(p), group_id: group.id })))
    if (participantError) {
      await supabase.from('groups').delete().eq('id', group.id)
      fail(participantError, "Couldn't save participants. Please try again.")
    }
  }

  return group.id as string
}

export async function updateExchangeDetails(id: string, details: ExchangeDetailsInput): Promise<void> {
  const { error } = await getSupabase().from('groups').update(groupPayload(details)).eq('id', id)
  if (error) fail(error, "Couldn't save your changes. Please try again.")
}

export async function addParticipant(groupId: string, input: ParticipantInput): Promise<void> {
  const { error } = await getSupabase()
    .from('participants')
    .insert({ ...participantPayload(input), group_id: groupId })
  if (error) fail(error, "Couldn't add this participant. Please try again.")
}

export async function updateParticipant(id: string, input: ParticipantInput): Promise<void> {
  const { error } = await getSupabase().from('participants').update(participantPayload(input)).eq('id', id)
  if (error) fail(error, "Couldn't update this participant. Please try again.")
}

export async function removeParticipant(id: string): Promise<void> {
  const { error } = await getSupabase().from('participants').delete().eq('id', id)
  if (error) fail(error, "Couldn't remove this participant. Please try again.")
}

/**
 * Called after the participant list changes. Any existing draw no longer
 * matches the list, so clear it and return the group to an undrawn status.
 */
export async function syncStatusAfterParticipantChange(groupId: string, participantCount: number): Promise<void> {
  const supabase = getSupabase()
  const { error: clearError } = await supabase.from('assignments').delete().eq('group_id', groupId)
  if (clearError) fail(clearError, "Couldn't update the exchange. Please try again.")
  const { error } = await supabase
    .from('groups')
    .update({ status: statusForParticipantCount(participantCount) })
    .eq('id', groupId)
  if (error) fail(error, "Couldn't update the exchange. Please try again.")
}

export async function drawExchange(groupId: string): Promise<{ participantCount: number; usedDoubleGifts: boolean }> {
  return invokeFunction('draw-exchange', { groupId })
}

/** Existing RLS only allows deleting exchanges that have not been drawn. */
export async function deleteExchange(id: string): Promise<void> {
  const { data, error } = await getSupabase().from('groups').delete().eq('id', id).select('id')
  if (error) fail(error, "Couldn't delete this exchange. Please try again.")
  if (!data?.length) throw new Error('Exchanges that have already been drawn cannot be deleted.')
}
